draw(A--B--K--cycle,linewidth(0.7));
draw(D--C--M--cycle,linewidth(0.7));
draw(K--L--M--I--cycle,linewidth(0.7));
label("$A$",A,SE);
label("$B$",B,SW);
label("$C$",C,NW);
label("$D$",D,NE);
label("$K$",K,N);
label("$L$",L,E);
label("$M$",M,S);
label("$N$",I,W);

[/asy]
